-- ETAPA 29: private inbox and idempotent, email-ready delivery queue.
create table public.notification_preferences (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,user_id uuid not null references auth.users(id) on delete cascade,in_app_enabled boolean not null default true,email_enabled boolean not null default false,quiet_hours_start time,quiet_hours_end time,timezone text not null default 'America/Bogota',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,user_id),check((quiet_hours_start is null and quiet_hours_end is null) or (quiet_hours_start is not null and quiet_hours_end is not null)));
create table public.notification_templates (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,event_type text not null check(event_type ~ '^[a-z][a-z0-9_.-]{2,119}$'),channel text not null check(channel in ('in_app','email')),version_number integer not null check(version_number>0),title_template text not null check(length(btrim(title_template)) between 1 and 160),body_template text not null check(length(btrim(body_template)) between 1 and 500),status text not null default 'draft' check(status in ('draft','approved','archived')),approved_at timestamptz,approved_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),unique(organization_id,event_type,channel,version_number));
create table public.notifications (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,domain_event_id uuid not null references public.domain_events(id) on delete restrict,recipient_user_id uuid not null references auth.users(id) on delete cascade,channel text not null check(channel in ('in_app','email')),priority text not null default 'normal' check(priority in ('low','normal','high','critical')),title text not null check(length(btrim(title)) between 1 and 160),body text not null check(length(btrim(body)) between 1 and 500),safe_link text check(safe_link is null or safe_link ~ '^/org/[0-9a-f-]{36}(/[a-zA-Z0-9_/?=&.-]*)?$'),read_at timestamptz,status text not null default 'pending' check(status in ('pending','queued','delivered','read','suppressed','failed')),created_at timestamptz not null default now(),unique(domain_event_id,recipient_user_id,channel));
create table public.notification_deliveries (id uuid primary key default gen_random_uuid(),notification_id uuid not null unique references public.notifications(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete restrict,channel text not null check(channel='email'),status text not null default 'pending' check(status in ('pending','processing','delivered','failed','discarded')),attempt_count integer not null default 0 check(attempt_count>=0),available_at timestamptz not null default now(),locked_at timestamptz,locked_by text,delivered_at timestamptz,last_error text check(last_error is null or length(last_error)<=500),idempotency_key uuid not null unique default gen_random_uuid(),created_at timestamptz not null default now());
create index notification_preferences_user_idx on public.notification_preferences(user_id,organization_id); create index notifications_recipient_inbox_idx on public.notifications(recipient_user_id,organization_id,read_at,created_at desc); create index notifications_event_idx on public.notifications(domain_event_id); create index notification_deliveries_consumer_idx on public.notification_deliveries(status,available_at) where status in ('pending','failed');
insert into public.permissions(code,module,action,description) values ('notifications.read','notifications','read','Consultar la bandeja de notificaciones.'),('notifications.manage','notifications','manage','Gestionar preferencias y plantillas.'),('notifications.templates_approve','notifications','templates_approve','Aprobar plantillas de notificación.') on conflict(code) do nothing;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r join public.permissions p on p.code like 'notifications.%' where r.code='organization_admin' and r.organization_id is null on conflict do nothing;
create or replace function private.validate_notification_links() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_table_name='notification_preferences' and not exists(select 1 from public.organization_members where organization_id=new.organization_id and user_id=new.user_id and status='active') then raise exception 'notification preference requires active membership' using errcode='23514'; end if; if tg_table_name='notifications' and not exists(select 1 from public.domain_events where id=new.domain_event_id and organization_id=new.organization_id) then raise exception 'notification event belongs to another organization' using errcode='23514'; end if; if tg_table_name='notification_deliveries' and not exists(select 1 from public.notifications where id=new.notification_id and organization_id=new.organization_id and channel='email') then raise exception 'notification delivery belongs to another organization' using errcode='23514'; end if; return new; end; $$;
create or replace function private.consume_event_for_notifications(p_event_id uuid) returns integer language plpgsql security definer set search_path='' as $$ declare e public.domain_events%rowtype; m record; t public.notification_templates%rowtype; p public.notification_preferences%rowtype; n uuid; total integer:=0; begin select * into e from public.domain_events where id=p_event_id; if not found then raise exception 'domain event not found'; end if; for m in select user_id from public.organization_members where organization_id=e.organization_id and status='active' loop select * into p from public.notification_preferences where organization_id=e.organization_id and user_id=m.user_id; select * into t from public.notification_templates where organization_id=e.organization_id and event_type=e.event_type and channel='in_app' and status='approved' order by version_number desc limit 1; if found and coalesce(p.in_app_enabled,true) then insert into public.notifications(organization_id,domain_event_id,recipient_user_id,channel,priority,title,body,safe_link,status) values(e.organization_id,e.id,m.user_id,'in_app',case when e.event_type like '%.overdue' then 'high' else 'normal' end,t.title_template,t.body_template,'/org/'||e.organization_id||'/dashboard','delivered') on conflict(domain_event_id,recipient_user_id,channel) do nothing returning id into n; if n is not null then total:=total+1; end if; end if; select * into t from public.notification_templates where organization_id=e.organization_id and event_type=e.event_type and channel='email' and status='approved' order by version_number desc limit 1; if found and coalesce(p.email_enabled,false) then insert into public.notifications(organization_id,domain_event_id,recipient_user_id,channel,priority,title,body,safe_link,status) values(e.organization_id,e.id,m.user_id,'email','normal',t.title_template,t.body_template,'/org/'||e.organization_id||'/dashboard','queued') on conflict(domain_event_id,recipient_user_id,channel) do nothing returning id into n; if n is not null then insert into public.notification_deliveries(notification_id,organization_id,channel) values(n,e.organization_id,'email'); total:=total+1; end if; end if; end loop; return total; end; $$;
create or replace function private.claim_notification_deliveries(p_worker_id text,p_limit integer default 20) returns setof public.notification_deliveries language plpgsql security definer set search_path='' as $$ begin if p_limit<1 or p_limit>100 then raise exception 'invalid delivery batch size'; end if; return query with c as (select id from public.notification_deliveries where status in ('pending','failed') and available_at<=now() order by available_at for update skip locked limit p_limit) update public.notification_deliveries d set status='processing',locked_at=now(),locked_by=p_worker_id,attempt_count=d.attempt_count+1 from c where d.id=c.id returning d.*; end; $$;
revoke all on function private.validate_notification_links(),private.consume_event_for_notifications(uuid),private.claim_notification_deliveries(text,integer) from public,anon,authenticated,service_role;
alter table public.notification_preferences enable row level security; alter table public.notification_templates enable row level security; alter table public.notifications enable row level security; alter table public.notification_deliveries enable row level security;
grant select,insert,update on public.notification_preferences,public.notification_templates,public.notifications to authenticated;
create policy notification_preferences_read on public.notification_preferences for select to authenticated using(user_id=(select auth.uid()) or (select private.has_permission(organization_id,'notifications.manage'))); create policy notification_preferences_write on public.notification_preferences for all to authenticated using(user_id=(select auth.uid()) or (select private.has_permission(organization_id,'notifications.manage'))) with check(user_id=(select auth.uid()) or (select private.has_permission(organization_id,'notifications.manage')));
create policy notification_templates_read on public.notification_templates for select to authenticated using((select private.has_permission(organization_id,'notifications.read'))); create policy notification_templates_write on public.notification_templates for all to authenticated using((select private.has_permission(organization_id,'notifications.manage'))) with check((select private.has_permission(organization_id,'notifications.manage')));
create policy notifications_recipient_read on public.notifications for select to authenticated using(recipient_user_id=(select auth.uid())); create policy notifications_recipient_update on public.notifications for update to authenticated using(recipient_user_id=(select auth.uid())) with check(recipient_user_id=(select auth.uid()));
create trigger notification_preferences_links before insert or update on public.notification_preferences for each row execute function private.validate_notification_links(); create trigger notifications_links before insert on public.notifications for each row execute function private.validate_notification_links(); create trigger notification_deliveries_links before insert on public.notification_deliveries for each row execute function private.validate_notification_links(); create trigger notification_preferences_updated before update on public.notification_preferences for each row execute function private.set_updated_at(); create trigger notifications_audit after insert or update on public.notifications for each row execute function private.capture_core_audit(); notify pgrst,'reload schema';
